const webhook = $('Input from Website').first().json;
const headers = webhook.headers ?? {};
const forwardedFor = headers['x-forwarded-for'];

if (typeof forwardedFor !== 'string' || !forwardedFor.trim()) {
  throw new Error('Trusted client IP header is missing.');
}

const clientIp = forwardedFor.split(',')[0].trim();

const staticData = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
const MAX_DAILY_PER_IP = 5;

if (staticData.quotaDay !== today) {
  staticData.quotaDay = today;
  staticData.ipCounts = {};
}

staticData.ipCounts ??= {};

const currentCount = staticData.ipCounts[clientIp] ?? 0;
const allowed = currentCount < MAX_DAILY_PER_IP;
const count = allowed ? currentCount + 1 : currentCount;

staticData.ipCounts[clientIp] = count;

return [{
  json: {
    ...$input.first().json,
    allowed,
    count,
    remaining: Math.max(0, MAX_DAILY_PER_IP - count)
  }
}];

const input = $input.first().json.body;

const ingredients = input?.ingredients;
const settings = input?.settings;

const isValidIngredients =
  Array.isArray(ingredients) &&
  ingredients.length > 0;

const isValidSettings =
  typeof settings === "object" &&
  settings !== null &&
  !Array.isArray(settings);

if (!isValidIngredients || !isValidSettings) {
  throw new Error("Invalid request structure");
}

const validNames = ingredients.every(ingredient => {
  return typeof ingredient.name === "string"
    && ingredient.name.trim().length > 0;
});

if (!validNames) {
  throw new Error("Invalid ingredient name");
}

const validAmounts = ingredients.every(ingredient => {
  return Number.isFinite(ingredient.amount)
    && ingredient.amount > 0;
});

if (!validAmounts) {
  throw new Error("Invalid ingredient amount");
}

const allowedUnits = ["g", "ml", "piece"];
const validUnit = ingredients.every(ingredient => {
  return allowedUnits.includes(ingredient.unit)
});

if (!validUnit) {
  throw new Error("Invalid ingredient unit");
}

const validPersons = Number.isInteger(settings.persons) && settings.persons > 0

if (!validPersons) {
  throw new Error("Invalid person amount");
}

const validPortions = Number.isInteger(settings.portions) && settings.portions > 0

if (!validPortions) {
  throw new Error("Invalid portions amount");
}

const allowedComplexities = ['Quick', 'Medium', 'Complex']
const validComplexity = allowedComplexities.includes(settings.complexity) 

if (!validComplexity) {
  throw new Error("Invalid complexity");
}

const allowedCuisines = [
  'German',
  'Italian',
  'Indian',
  'Japanese',
  'Gourmet',
  'Fusion'
];
const validCuisine =
  typeof settings.cuisine === 'string' &&
  allowedCuisines.some(allowedCuisine =>
    allowedCuisine.toLowerCase() === settings.cuisine.toLowerCase()
  );

if (!validCuisine) {
  throw new Error("Invalid cuisine");
}

const allowedPreferences = [
  "Vegetarian",
  "Vegan",
  "Keto",
  "No preferences"
];

const validPreferences =
  typeof settings.preferences === "string" &&
  allowedPreferences.some(preference =>
    preference.toLowerCase() === settings.preferences.toLowerCase()
  );

if (!validPreferences) {
  throw new Error("Invalid preferences");
}

return [
  {
    json: {
      ingredients,
      settings
    }
  }
];

