const rawOutput = $input.first().json.output;

const settings = $('Input from Website').first().json.body.settings

let output;

try {
  output = typeof rawOutput === "string"
    ? JSON.parse(rawOutput)
    : rawOutput;
} catch (error) {
  return [{
    json: {
      valid: false,
      error: "AI output is not valid JSON",
      details: String(error)
    }
  }];
}

const recipes = output?.recipes;

if (!Array.isArray(recipes) || recipes.length !== 3) {
  return [{
    json: {
      valid: false,
      error: "Expected exactly 3 recipes",
      received: Array.isArray(recipes) ? recipes.length : null
    }
  }];
}

function isObject(value) {
  return value !== null &&
    typeof value === "object" &&
    !Array.isArray(value);
}

function isNonEmptyString(value) {
  return typeof value === "string" &&
    value.trim().length > 0;
}

function isPositiveNumber(value) {
  return Number.isFinite(value) && value > 0;
}

function isAllowedValue(value, allowedValues) {
  return typeof value === "string" &&
    allowedValues.some(allowed =>
      allowed.toLowerCase() === value.toLowerCase()
    );
}

function isValidIngredient(ingredient) {
  const allowedUnits = [
    "g", "kg", "ml", "l",
    "piece", "pieces", "bunch",
    "tbsp", "tsp", "clove", "cloves"
  ];

  return isObject(ingredient) &&
    isNonEmptyString(ingredient.name) &&
    isPositiveNumber(ingredient.amount) &&
    allowedUnits.includes(ingredient.unit);
}

function isValidNutrition(nutritions) {
  if (!isObject(nutritions)) return false;

  const requiredFields = [
    "calories",
    "protein",
    "carbohydrates",
    "fat"
  ];

  return requiredFields.every(field =>
    Number.isFinite(nutritions[field]) &&
    nutritions[field] >= 0
  );
}

function isValidDirections(directions, cookingPerson) {
  return Array.isArray(directions) &&
    directions.length >= 3 &&
    directions.every(direction =>
      isObject(direction) &&
      isNonEmptyString(direction.headline) &&
      isNonEmptyString(direction.description) &&
      Number.isInteger(direction.chef) &&
      direction.chef >= 1 &&
      direction.chef <= cookingPerson
    );
}

function debugRecipe(recipe) {
  if (!isObject(recipe)) {
    return ["Recipe is not an object"];
  }

  const allowedCuisines = [
    "German", "Italian", "Indian",
    "Japanese", "Gourmet", "Fusion"
  ];

  const allowedComplexities = [
    "Quick", "Medium", "Complex"
  ];

  const allowedPreferences = [
    "Vegetarian", "Vegan",
    "Keto", "No preferences"
  ];

  const checks = {
    name: isNonEmptyString(recipe.name),

    cuisine: isAllowedValue(
      recipe.cuisine, allowedCuisines
    ),

    cookingTime:
      Number.isInteger(recipe.cookingTime) &&
      recipe.cookingTime > 0,

    cookingPerson:
      Number.isInteger(recipe.cookingPerson) &&
      recipe.cookingPerson === settings.persons,

    preferences: isAllowedValue(
      recipe.preferences, allowedPreferences
    ),

    complexity: isAllowedValue(
      recipe.complexity, allowedComplexities
    ),

    likes: recipe.likes === 0,

    ingredients:
      Array.isArray(recipe.ingredients) &&
      recipe.ingredients.length > 0 &&
      recipe.ingredients.every(isValidIngredient),

    extraIngredients:
      Array.isArray(recipe.extraIngredients) &&
      recipe.extraIngredients.every(isValidIngredient),

    directions: isValidDirections(
      recipe.directions,
      recipe.cookingPerson
    ),

    nutritions: isValidNutrition(recipe.nutritions)
  };

  return Object.entries(checks)
    .filter(([field, valid]) => !valid)
    .map(([field]) => field);
}

const validationResults = recipes.map((recipe, index) => ({
  recipe: index + 1,
  name: recipe?.name ?? null,
  errors: debugRecipe(recipe)
}));

const valid = validationResults.every(
  result => result.errors.length === 0
);

return [{
  json: {
    valid,
    validationResults,
    output: JSON.stringify({ recipes })
  }
}];

